              <article className="evidence-card"><div className="evidence-icon"><Database size={18} /></div><span className="card-kicker">MULTI-CONTRACT CONTEXT</span><strong>{contractChurn.revalidation.events_with_multiple_active_subscriptions} / {contractChurn.revalidation.events_with_any_active_subscription}</strong><p>Conflicting event rows with more than one active subscription on the event date.</p></article>
