            <label className="select-label">Compare by outcome <select value={businessLabel} onChange={(e) => setBusinessLabel(e.target.value as BusinessLabel)}>{Object.entries(labelNames).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></label>
